productIcons.push('insights');expNames.push('Client Health');expLabels.push('CLIENT INTELLIGENCE');expMenu.push(['Portfolio overview','Client accounts','Signals & evidence','Action plans']);
studioGroups.Delivery.push(13);
productStories.push({audience:'Client success & leadership',title:'Understand the relationship. Protect the renewal.',desc:'A shared view of client health, with explainable signals and accountable next steps.',output:'Account health + evidence + prioritized action plans'});
showcaseMeta.push(['Explore client health','Client portfolio','Explainable health scores','Renewal exposure','Account action plans',0]);
studioProductDetails.push(['Understand the relationship. Protect the renewal.','Bring delivery, engagement, satisfaction, and commercial signals together so your team can see which clients are thriving, where relationships need attention, and what to do next.',[['See the whole relationship','Combine adoption, sentiment, delivery performance, and commercial context into an explainable account score.'],['Understand the change','Inspect the evidence behind a declining score and distinguish a weak signal from a confirmed concern.'],['Act before renewal','Assign an owner, prepare a recovery plan, and track the actions that strengthen the relationship.']],['Claude API and OpenAI API can summarize account evidence, explain changes, and draft recovery or expansion plans for review.','Connect Microsoft Teams relationship discussions with SharePoint reviews and deliverables, subject to the client’s access rules.','Supabase can hold account snapshots and action history; Vercel serves the workspace, with Azure supporting enterprise data and identity integrations.']]);
let healthFilter='All',healthQuery='';
const healthAccounts=[
{id:0,name:'Northstar Manufacturing',sector:'Manufacturing',owner:'Alex Morgan',arr:180000,days:42,metrics:[42,58,63,65],prior:68,trend:[76,74,70,68,62,56],signal:'Executive sponsor missed two reviews',source:'Account review · Oct 16',detail:'Sponsor attendance fell from 3 of 3 meetings to 1 of 3. Weekly active users fell from 42 to 29. Confirm whether priorities or ownership have changed.',next:'Schedule a sponsor reset and agree on two measurable outcomes.'},
{id:1,name:'Harbor Financial',sector:'Financial services',owner:'Taylor Kim',arr:240000,days:85,metrics:[92,88,94,86],prior:87,trend:[78,81,83,87,89,90],signal:'Strong adoption across a second department',source:'Usage snapshot · Oct 18',detail:'Active usage increased 18% in the sample period. The operations team requested access for an additional department, while delivery milestones remain on schedule.',next:'Validate the expansion use case with the department lead.'},
{id:2,name:'Cedar Health Partners',sector:'Healthcare',owner:'Jordan Ellis',arr:150000,days:27,metrics:[65,54,68,72],prior:73,trend:[81,79,76,73,69,64],signal:'Unresolved reporting issue ahead of renewal',source:'Support review · Oct 17',detail:'Two reporting issues remain open after 12 days. The client expressed concern about data reconciliation in the last review. Renewal is within 30 days.',next:'Agree on a resolution owner and recovery checkpoint before renewal.'},
{id:3,name:'Summit Logistics',sector:'Logistics',owner:'Alex Morgan',arr:120000,days:124,metrics:[82,80,87,84],prior:80,trend:[73,76,78,80,82,83],signal:'Delivery milestones completed on schedule',source:'Project review · Oct 18',detail:'All four delivery milestones were accepted this month. Weekly engagement is consistent and no overdue support items are recorded.',next:'Capture the outcome story and prepare the next value review.'},
{id:4,name:'Meridian Services',sector:'Professional services',owner:'Taylor Kim',arr:96000,days:61,metrics:[35,40,52,58],prior:59,trend:[74,69,64,59,51,44],signal:'Champion departure and declining engagement',source:'Relationship notes · Oct 15',detail:'The primary champion has left the company. No replacement sponsor is confirmed and active users have declined for three consecutive sample periods.',next:'Map a replacement sponsor and run a focused adoption session.'},
{id:5,name:'Oakfield Engineering',sector:'Engineering',owner:'Jordan Ellis',arr:132000,days:103,metrics:[77,83,79,85],prior:77,trend:[69,72,74,77,79,81],signal:'Positive review with new workflow requests',source:'Client review · Oct 16',detail:'The delivery lead rated the latest milestone positively and identified two adjacent workflows. Confirm the value already delivered before proposing scope.',next:'Prepare an outcome review and qualify the additional workflows.'}
];
let healthPlans=JSON.parse(localStorage.getItem('nine67-health-plans')||'null')||[{id:0,account:0,title:'Confirm executive sponsor priorities',owner:'Alex Morgan',due:'2026-10-23',status:'Open'},{id:1,account:2,title:'Resolve reporting reconciliation issues',owner:'Jordan Ellis',due:'2026-10-22',status:'Open'}];
function healthSave(){localStorage.setItem('nine67-health-plans',JSON.stringify(healthPlans))}
function healthScore(a){return Math.round(a.metrics[0]*.3+a.metrics[1]*.3+a.metrics[2]*.25+a.metrics[3]*.15)}
function healthBand(a){let n=healthScore(a);return n>=80?'Healthy':n>=60?'Watch':'At risk'}
function healthTone(a){return healthScore(a)>=80?'good':healthScore(a)>=60?'watch':'risk'}
function healthPill(a){return `<span class="health-pill ${healthTone(a)}">${healthBand(a)}</span>`}
function healthSpark(a,large=false){return `<svg class="health-spark ${large?'large':''}" viewBox="0 0 240 80" role="img" aria-label="Six illustrative weekly health scores: ${a.trend.join(', ')}"><path d="M0 65H240M0 35H240" fill="none" stroke="#ece8e2"/><polyline points="${a.trend.map((v,i)=>`${i*48},${80-v*.7}`).join(' ')}" fill="none" stroke="${healthTone(a)==='risk'?'#b57461':'#8d785f'}" stroke-width="2.5"/>${a.trend.map((v,i)=>`<circle cx="${i*48}" cy="${80-v*.7}" r="3" fill="#9a7a59"/>`).join('')}</svg>`}
function healthSelect(f){healthFilter=f;tab=1;render()}
function healthMethods(){draw('How client health is calculated',`<p>Scores are illustrative and explainable, not predictions of churn.</p><div class="health-method">${[['Engagement',30],['Sentiment',30],['Delivery',25],['Commercial',15]].map(([n,v])=>`<p><b>${n}</b><span>${v}% weight</span></p>`).join('')}</div><p>Weighted score = engagement × 30% + sentiment × 30% + delivery × 25% + commercial × 15%, rounded to the nearest whole number.</p><p><b>Healthy:</b> 80–100 · <b>Watch:</b> 60–79 · <b>At risk:</b> below 60.</p><p>Annual contract value flagged for attention is the full value of Watch and At-risk accounts; it is not expected lost revenue. Completing an action does not automatically improve health.</p><p>All account data, trends, and AI analysis in this demo are simulated. Actual implementations require agreed source definitions, freshness checks, and human review.</p>`)}
function healthAccount(id){const a=healthAccounts[id],n=healthScore(a);draw(a.name,`<div class="health-account-head"><div><span class="health-big">${n}<small>/100</small></span>${healthPill(a)}</div><p>${esc(a.sector)} · ${esc(a.owner)}<br>${money(a.arr)} annual value · Renewal in ${a.days} days</p></div>${healthSpark(a,true)}<p class="exp-note">Six illustrative weekly snapshots · Latest score ${n}</p><h3>What is driving the score?</h3>${['Engagement','Sentiment','Delivery','Commercial'].map((x,i)=>`<div class="health-driver"><span>${x}</span><div><i style="width:${a.metrics[i]}%"></i></div><b>${a.metrics[i]}</b></div>`).join('')}<div class="health-evidence"><small>${esc(a.source)} · Sample evidence</small><h3>${esc(a.signal)}</h3><p>${esc(a.detail)}</p></div><h3>Recommended next step</h3><p>${esc(a.next)}</p><div class="health-buttons">${ib('Draft action plan',`healthDraft(${id})`,'spark','primary')}${ib('Explore health scenario',`healthScenario(${id})`,'forecast')}${ib('Scoring method','healthMethods()','help')}</div>`)}
function healthDraft(id){const a=healthAccounts[id];draw('Action plan · '+a.name,`<p class="exp-note">Simulated AI draft · Review and edit before saving.</p><div class="health-evidence"><h3>Why this account needs this action</h3><p>${esc(a.detail)}</p></div><label class="health-label">Action<textarea id="healthTask">${esc(a.next)}</textarea></label><label class="health-label">Accountable owner<select id="healthOwner">${['Alex Morgan','Taylor Kim','Jordan Ellis'].map(n=>`<option ${n===a.owner?'selected':''}>${n}</option>`).join('')}</select></label><label class="health-label">Due date<input type="date" id="healthDue" value="2026-10-26"></label><p>Success check: confirm the client’s priorities, record the agreed outcome, and review the relevant health signals at the next checkpoint.</p>${ib('Save action plan',`healthAdd(${id})`,'check','primary')}`)}
function healthAdd(id){const title=$('#healthTask').value.trim(),due=$('#healthDue').value;if(!title||!due){toast('Add an action and due date');return}healthPlans.push({id:Date.now(),account:id,title,owner:$('#healthOwner').value,due,status:'Open'});healthSave();closeDrawer();tab=3;render();toast('Action plan saved in this browser')}
function healthToggle(id){const p=healthPlans.find(x=>x.id===id);p.status=p.status==='Open'?'Complete':'Open';healthSave();render()}
function healthScenario(id){const a=healthAccounts[id];draw('Health scenario · '+a.name,`<p>Explore how engagement would affect the weighted score. This does not change the account or predict a business outcome.</p><div class="health-scenario"><div>Current score<b>${healthScore(a)}</b></div><div>Scenario score<b id="healthScenarioScore">${healthScore(a)}</b></div></div><label class="health-label">Engagement <output id="healthEngagement">${a.metrics[0]}</output> / 100<input type="range" min="0" max="100" value="${a.metrics[0]}" oninput="healthScenarioUpdate(${id},this.value)"></label><p class="exp-note">Sentiment, delivery, and commercial inputs remain fixed. Engagement contributes 30% of the total.</p>`)}
function healthScenarioUpdate(id,v){const a=healthAccounts[id];$('#healthEngagement').textContent=v;$('#healthScenarioScore').textContent=Math.round(Number(v)*.3+a.metrics[1]*.3+a.metrics[2]*.25+a.metrics[3]*.15)}
function healthBrief(){const flagged=healthAccounts.filter(a=>healthScore(a)<60);draw('Portfolio briefing',`<span class="health-pill watch">Simulated AI analysis</span><h2>Two relationships need a proactive reset.</h2><p>${flagged.map(a=>esc(a.name)).join(' and ')} are below the healthy range. Their combined annual contract value is ${money(flagged.reduce((s,a)=>s+a.arr,0))}; this is exposure for review, not predicted loss.</p><h3>Prioritize the next 30 days</h3><p>Cedar Health Partners renews in 27 days. Resolve the reporting issue, confirm acceptance with the client, and document the renewal decision path.</p><h3>Protect the sponsor relationship</h3><p>Northstar needs an executive reset. Meridian needs a replacement champion. Treat these as separate relationship issues with named owners.</p><h3>Grow from demonstrated value</h3><p>Harbor’s adoption is strengthening. Validate the second department’s needs before proposing an expansion.</p>${ib('Review signals','closeDrawer();tab=2;render()','arrow','primary')}`)}
function healthRows(){const list=healthAccounts.filter(a=>(healthFilter==='All'||healthFilter==='Needs attention'&&healthScore(a)<80||healthBand(a)===healthFilter||healthFilter==='Renewing soon'&&a.days<=90)&&(!healthQuery||(a.name+' '+a.owner+' '+a.sector).toLowerCase().includes(healthQuery.toLowerCase())));return list.length?`<div class="health-table-scroll"><table class="health-table"><thead><tr><th>Client / account owner</th><th>Health</th><th>6-week trend</th><th>Annual value</th><th>Renewal</th><th>Primary signal</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><div class="health-account-cell"><span class="health-avatar">${a.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</span><div><button class="health-account-link" onclick="healthAccount(${a.id})">${esc(a.name)}</button><small>${esc(a.owner)} · ${esc(a.sector)}</small></div></div></td><td><div class="health-score-cell"><b>${healthScore(a)}</b><span class="health-score-track"><i style="width:${healthScore(a)}%" class="${healthTone(a)}"></i></span></div>${healthPill(a)}</td><td>${healthSpark(a)}</td><td>${money(a.arr)}</td><td>${a.days} days</td><td class="health-signal-cell">${esc(a.signal)}</td><td><button aria-label="Open ${esc(a.name)}" onclick="healthAccount(${a.id})">↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="health-empty">No accounts match this filter. Try another status or client name.</div>'}
function healthSearch(v){healthQuery=v;$('#healthRows').innerHTML=healthRows()}
function healthExperience(){const total=healthAccounts.reduce((s,a)=>s+a.arr,0),avg=Math.round(healthAccounts.reduce((s,a)=>s+healthScore(a),0)/healthAccounts.length);return `<div class="experience health-product">${expHeader(13,ib('AI portfolio briefing','healthBrief()','spark','primary'),ib('Scoring method','healthMethods()','help'))}<div class="health-body"><div class="health-heading"><div><span class="micro-label">RELATIONSHIP INTELLIGENCE</span><h1>${['Client relationships, in focus.','Your client portfolio','The evidence behind the score','Turn insight into ownership'][tab]}</h1><p>${['A shared view of engagement, delivery, sentiment, and renewal readiness.','Open an account to inspect health drivers, evidence, and next steps.','Review account signals before deciding on a recovery or growth action.','Track the work that improves the relationship. Scores remain evidence-driven.'][tab]}</p></div><span class="health-snapshot"><i></i> DEMO WORKSPACE<br><b>19 Oct 2026 <span>·</span> 6 accounts</b></span></div>${tab===0?healthOverview():''}${tab===1?`<div class="health-filterbar"><div>${['All','Healthy','Watch','At risk','Needs attention','Renewing soon'].map(f=>`<button class="${f===healthFilter?'active':''}" onclick="healthFilter='${f}';render()">${f}</button>`).join('')}</div><input type="search" aria-label="Search clients" placeholder="Search clients or owners…" value="${esc(healthQuery)}" oninput="healthSearch(this.value)"></div><div id="healthRows">${healthRows()}</div>`:''}${tab===2?`<div class="health-signals">${[...healthAccounts].sort((a,b)=>healthScore(a)-healthScore(b)).map(a=>`<section class="health-panel"><div class="health-panel-title">${healthPill(a)}<span>${esc(a.source)}</span></div><h2>${esc(a.signal)}</h2><p class="health-client-caption">${esc(a.name)}</p><p>${esc(a.detail)}</p><div class="health-buttons">${ib('Inspect evidence',`healthAccount(${a.id})`,'arrow')}${ib('Draft action',`healthDraft(${a.id})`,'spark','link')}</div></section>`).join('')}</div>`:''}${tab===3?`<div class="health-plan-summary"><b>${healthPlans.filter(p=>p.status==='Open').length} open actions</b><span>${healthPlans.filter(p=>p.status==='Complete').length} complete</span>${ib('Create action','healthChooseAccount()','plus','primary')}</div>${healthPlans.map(p=>`<section class="health-plan"><button class="health-check ${p.status==='Complete'?'done':''}" aria-label="${p.status==='Open'?'Complete':'Reopen'} action" onclick="healthToggle(${p.id})">${icon(p.status==='Complete'?'check':'plus')}</button><div><h3>${esc(p.title)}</h3><p>${esc(healthAccounts[p.account].name)} · ${esc(p.owner)} · Due ${esc(p.due)}</p></div><span class="health-pill ${p.status==='Complete'?'good':'watch'}">${p.status}</span>${ib('Account',`healthAccount(${p.account})`,'arrow','link')}</section>`).join('')}`:''}<p class="health-footnote">Illustrative account data · Simulated analysis · Actions saved in this browser · No client messages sent</p></div></div>`}
function healthChooseAccount(){draw('Choose a client',`<p>Select the account for your action plan.</p>${healthAccounts.map(a=>`<p>${ib(a.name,`healthDraft(${a.id})`,'arrow')}</p>`).join('')}`)}
function healthOverview(){const avg=Math.round(healthAccounts.reduce((s,a)=>s+healthScore(a),0)/6),values=healthAccounts.map(a=>a.arr),total=values.reduce((x,y)=>x+y,0),attention=healthAccounts.filter(a=>healthScore(a)<80),trend=[0,1,2,3,4,5].map(i=>Math.round(healthAccounts.reduce((s,a)=>s+a.trend[i],0)/6));return `<div class="health-executive"><section class="health-rating-card"><div class="health-card-eyebrow">PORTFOLIO HEALTH ${ib('Method','healthMethods()','help','link')}</div><div class="health-rating-number">${avg}<span>/ 100</span></div><div class="health-rating-caption"><span class="health-change">${trend[5]-trend[0]} pts</span> over six sample weeks</div><div class="health-rating-rule"><i style="width:${avg}%"></i></div><p>Three healthy relationships.<br>Three need a closer look.</p><button class="health-text-action" onclick="healthSelect('Needs attention')">Review accounts needing attention ${icon('arrow')}</button></section><section class="health-trend-card"><div class="health-panel-title"><div><h2>Relationship momentum</h2><p>Portfolio average · Last six sample weeks</p></div><span class="health-chart-legend"><i></i> Health score</span></div><svg class="health-trend-chart" viewBox="0 0 620 190" role="img" aria-label="Portfolio weekly health scores ${trend.join(', ')}"><defs><linearGradient id="healthTrendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b49a7d" stop-opacity=".22"/><stop offset="100%" stop-color="#b49a7d" stop-opacity="0"/></linearGradient></defs>${[40,60,80,100].map(v=>`<line x1="35" y1="${160-(v-40)*2}" x2="600" y2="${160-(v-40)*2}" stroke="#eeece8"/><text x="3" y="${164-(v-40)*2}" fill="#9b9389" font-size="10">${v}</text>`).join('')}<line x1="35" y1="80" x2="600" y2="80" stroke="#b5baa9" stroke-dasharray="4 5"/><path d="M35 170 L${trend.map((v,i)=>`${35+i*110} ${160-(v-40)*2}`).join(' L')} L585 170Z" fill="url(#healthTrendFill)"/><polyline points="${trend.map((v,i)=>`${35+i*110},${160-(v-40)*2}`).join(' ')}" fill="none" stroke="#9e8162" stroke-width="2.5"/>${trend.map((v,i)=>`<circle cx="${35+i*110}" cy="${160-(v-40)*2}" r="4" fill="white" stroke="#9e8162" stroke-width="2"/><text x="${35+i*110}" y="${148-(v-40)*2}" text-anchor="middle" font-size="11" fill="#83694f">${v}</text><text x="${35+i*110}" y="187" text-anchor="middle" font-size="10" fill="#9b9389">W${i+1}</text>`).join('')}</svg><div class="health-trend-footer"><span>Healthy threshold: 80</span><button onclick="healthMethods()">View scoring methodology ↗</button></div></section></div><div class="health-metric-strip">${[['Annual client value',money(total),'Across 6 active relationships',"healthSelect('All')"],['Value needing attention',money(attention.reduce((s,a)=>s+a.arr,0)),'Full value of Watch + At-risk accounts',"healthSelect('Needs attention')"],['Renewals within 90 days','4 accounts','Review commercial readiness',"healthSelect('Renewing soon')"],['Open relationship actions',healthPlans.filter(p=>p.status==='Open').length,'Assigned next steps to move forward',"tab=3;render()"]].map(([l,v,c,f])=>`<button onclick="${f}"><span>${l}</span><b>${v}</b><small>${c}</small>${icon('arrow')}</button>`).join('')}</div><div class="health-middle-grid"><section class="health-panel health-coverage"><div class="health-panel-title"><h2>Relationship mix</h2><span>By account count</span></div><div class="health-mix-content"><div class="health-donut" role="img" aria-label="3 healthy, 1 watch, 2 at risk"><div><b>6</b><span>CLIENTS</span></div></div><div class="health-mix-legend">${[['Healthy','good'],['Watch','watch'],['At risk','risk']].map(([f,c])=>`<button onclick="healthSelect('${f}')"><i class="${c}"></i><span>${f}</span><b>${healthAccounts.filter(a=>healthBand(a)===f).length}</b>${icon('arrow')}</button>`).join('')}</div></div></section><section class="health-panel health-focus"><div class="health-panel-title"><h2>Where to focus next</h2><button onclick="tab=2;render()">All signals ↗</button></div>${[2,4,0].map((id,i)=>{const a=healthAccounts[id];return `<button class="health-focus-row" onclick="healthAccount(${id})"><span class="health-focus-index">0${i+1}</span><div><b>${a.name}</b><small>${a.signal}</small></div><span class="health-focus-days">${a.days}d<small>to renewal</small></span>${icon('arrow')}</button>`}).join('')}</section></div><div class="health-register-heading"><div><h2>The client portfolio</h2><p>Signals, trends, and context behind every relationship.</p></div>${ib('All client accounts','healthFilter="All";tab=1;render()','arrow')}</div>${healthRows()}`}
if(location.hash==='#client-health')current=13;
render();
